import{_ as d,a0 as r,w as n,s as p,ao as l,I as t,x as e,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"網絡廣告商的像素追蹤是如何工作的？ | LCTT x X-CMD","titleTemplate":false,"description":"網絡廣告商的像素追蹤是如何工作的？ | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"網絡廣告商的像素追蹤是如何工作的？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"網絡廣告商的像素追蹤是如何工作的？ | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191218 How tracking pixels work","title":"網絡廣告商的像素追蹤是如何工作的？","tag":"201912","desc":""},"relativePath":"201912/20191218 How tracking pixels work.md","filePath":"[post].md"}'),c={name:"201912/20191218 How tracking pixels work.md"};function k(f,o,m,g,b,x){const a=r("Link");return n(),p("div",null,[o[29]||(o[29]=l('<h1 id="網絡廣告商的像素追蹤是如何工作的" tabindex="-1">網絡廣告商的像素追蹤是如何工作的？ <a class="header-anchor" href="#網絡廣告商的像素追蹤是如何工作的" aria-label="Permalink to “網絡廣告商的像素追蹤是如何工作的？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/27/214125hvpv4e5ijepa0aqj.jpg" alt=""></p><p>昨天，我和一名記者談到了一個問題：廣告商是如何在互聯網上對人們進行追蹤的？我們津津有味地查看了 Firefox 的開發者工具（雖然我不是一個互聯網隱私專家，但至少還會使用開發者工具中的“network”標籤頁），從中我終於弄明白<ruby>像素追蹤<rt>tracking pixels</rt></ruby>在實際中是如何工作的了。</p><h3 id="問題-facebook-怎麼知道你逛了-old-navy" tabindex="-1">問題：Facebook 怎麼知道你逛了 Old Navy？ <a class="header-anchor" href="#問題-facebook-怎麼知道你逛了-old-navy" aria-label="Permalink to “問題：Facebook 怎麼知道你逛了 Old Navy？”">​</a></h3><p>我時常聽人們説起這種有些詭異的上網經歷：你在線上瀏覽了一個商品，一天之後，竟然看到了同一款靴子（或者是別的什麼你當時瀏覽的商品）的廣告。這就是所謂的“再營銷”，但它到底是如何實現的呢？</p><p>在本文中，我們來進行一個小實驗，看看 Facebook 究竟是怎麼知道你在線上瀏覽了什麼商品的。這裏使用 Facebook 作為示例，只是因為很容易找到使用了 Facebook 像素追蹤技術的網站；其實，幾乎所有互聯網廣告公司都會使用類似的追蹤技術。</p><h3 id="準備-允許第三方追蹤器-同時關閉廣告攔截器" tabindex="-1">準備：允許第三方追蹤器，同時關閉廣告攔截器 <a class="header-anchor" href="#準備-允許第三方追蹤器-同時關閉廣告攔截器" aria-label="Permalink to “準備：允許第三方追蹤器，同時關閉廣告攔截器”">​</a></h3><p>我使用的瀏覽器是 Firefox，但是 Firefox 默認攔截了很多這種類型的追蹤，所以需要修改 Firefox 的隱私設置，才能讓這種追蹤生效。</p>',8)),t("p",null,[o[2]||(o[2]=e("首先，我將隱私設置從默認設置（",-1)),i(a,{href:"https://jvns.ca/images/trackers.png"},{default:s(()=>[...o[0]||(o[0]=[e("截圖",-1)])]),_:1}),o[3]||(o[3]=e("）修改為允許第三方追蹤器的個性化設置（",-1)),i(a,{href:"https://jvns.ca/images/firefox-insecure-settings.png"},{default:s(()=>[...o[1]||(o[1]=[e("截圖",-1)])]),_:1}),o[4]||(o[4]=e("），然後禁用了一些平時運行的隱私保護擴展。",-1))]),o[30]||(o[30]=l('<p><img src="https://jvns.ca/images/trackers.png" alt="截圖"></p><p><img src="https://jvns.ca/images/firefox-insecure-settings.png" alt="截圖"></p><h3 id="像素追蹤-關鍵不在於-gif-而在於請求參數" tabindex="-1">像素追蹤：關鍵不在於 gif，而在於請求參數 <a class="header-anchor" href="#像素追蹤-關鍵不在於-gif-而在於請求參數" aria-label="Permalink to “像素追蹤：關鍵不在於 gif，而在於請求參數”">​</a></h3><p>像素追蹤是網站用來追蹤你的一個 1x1 大小的 gif。就其本身而言，一個小小的 1x1 gif 顯然起不到什麼作用。那麼，像素追蹤到底是如何進行追蹤的？其中涉及兩個方面：</p><ol><li>通過使用像素追蹤上的<strong>請求參數</strong>，網站可以添加額外的信息，比如你正在訪問的頁面。這樣一來，請求的就不是 <code>https://www.facebook.com/tr/</code>（這個鏈接是一個 44 字節大小的 1x1 gif），而是 <code>https://www.facebook.com/tr/?the_website_you&#39;re_on</code>。（郵件營銷人員會使用類似的技巧，通過為像素追蹤指定一個獨特的 URL，弄清楚你是否打開了某一封郵件。）</li><li>在發送該請求的同時，還發送了相應的 cookie。這樣一來廣告商就可以知道，訪問 oldnavy.com 的這個人和在同一台電腦上使用 Facebook 的是同一個人。</li></ol><h3 id="old-navy-網站上的-facebook-像素追蹤" tabindex="-1">Old Navy 網站上的 Facebook 像素追蹤 <a class="header-anchor" href="#old-navy-網站上的-facebook-像素追蹤" aria-label="Permalink to “Old Navy 網站上的 Facebook 像素追蹤”">​</a></h3><p>為了對此進行驗證，我在 Old Navy（GAP 旗下的一個服裝品牌）網站上瀏覽了一個商品，相應的 URL 是 <code>https://oldnavy.gap.com/browse/product.do?pid=504753002&amp;cid=1125694&amp;pcid=1135640&amp;vid=1&amp;grid=pds_0_109_1</code>（這是一件“男款短絨格子花呢大衣”）。</p>',7)),t("p",null,[o[6]||(o[6]=e("在我瀏覽這個商品的同時，頁面上運行的 Javascript（用的應該是",-1)),i(a,{href:"https://developers.facebook.com/docs/facebook-pixel/implementation/"},{default:s(()=>[...o[5]||(o[5]=[e("這段代碼",-1)])]),_:1}),o[7]||(o[7]=e("）向 facebook.com 發送了一個請求。在開發者工具中，該請求看上去是這樣的：（我屏蔽了大部分 cookie 值，因為其中有一些是我的登錄 cookie）",-1))]),o[31]||(o[31]=l('<p><img src="https://jvns.ca/images/fb-old-navy.png" alt=""></p><p>下面對其進行拆解分析：</p><ol><li><p>我的瀏覽器向如下 URL 發送了一個請求；</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ol>',3)),t("p",null,[i(a,{href:"https://www.facebook.com/tr/?id=937725046402747&ev=PageView&dl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fproduct.do%3Fpid%3D504753002%26cid%3D1125694%26pcid%3Dxxxxxx0%26vid%3D1%26grid%3Dpds_0_109_1%23pdp-page-content&rl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fcategory.do%3Fcid%3D1135640%26mlink%3D5155%2Cm_mts_a&if=false&ts=1576684838096&sw=1920&sh=1080&v=2.9.15&r=stable&a=tmtealium&ec=0&o=30&fbp=fb.1.1576684798512.1946041422&it=15xxxxxxxxxx4&coo=false&rqm=GET"},{default:s(()=>[...o[8]||(o[8]=[e("https://www.facebook.com/tr/?id=937725046402747&ev=PageView&dl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fproduct.do%3Fpid%3D504753002%26cid%3D1125694%26pcid%3Dxxxxxx0%26vid%3D1%26grid%3Dpds_0_109_1%23pdp-page-content&rl=https%3A%2F%2Foldnavy.gap.com%2Fbrowse%2Fcategory.do%3Fcid%3D1135640%26mlink%3D5155%2Cm_mts_a&if=false&ts=1576684838096&sw=1920&sh=1080&v=2.9.15&r=stable&a=tmtealium&ec=0&o=30&fbp=fb.1.1576684798512.1946041422&it=15xxxxxxxxxx4&coo=false&rqm=GET",-1)])]),_:1})]),o[32]||(o[32]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2. 與該請求同時發送的，還有一個名為 `fr` 的 cookie，取值為</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>    ```</span></span>\n<span class="line"><span>10oGXEcKfGekg67iy.AWVdJq5MG3VLYaNjz4MTNRaU1zg.Bd-kxt.KU.F36.0.0.Bd-kx6.</span></span></code></pre></div><p>（估計是我的 Facebook 廣告追蹤 ID）</p><p>在所發送的像素追蹤查詢字符串裏，有三個值得注意的地方：</p><ul><li>我當前訪問的頁面：<code>https://oldnavy.gap.com/browse/product.do?pid=504753002&amp;cid=1125694&amp;pcid=1135640&amp;vid=1&amp;grid=pds_0_109_1#pdp-page-content</code></li><li>引導我來到當前頁面的上一級頁面：<code>https://oldnavy.gap.com/browse/category.do?cid=1135640&amp;mlink=5155,m_mts_a</code>；</li><li>作為我的身份標識的 cookie：<code>10oGXEcKfGekg67iy.AWVdJq5MG3VLYaNjz4MTNRaU1zg.Bd-kxt.KU.F36.0.0.Bd-kx6.</code></li></ul><h3 id="下面來逛逛-facebook" tabindex="-1">下面來逛逛 Facebook！ <a class="header-anchor" href="#下面來逛逛-facebook" aria-label="Permalink to “下面來逛逛 Facebook！”">​</a></h3><p>下面來逛逛 Facebook 吧。我之前已經登入了 Facebook，猜猜看，我的瀏覽器發送給 Facebook 的 cookie 是什麼？</p><p>不出所料，正是之前見過的 <code>fr</code> cookie：<code>10oGXEcKfGekg67iy.AWVdJq5MG3VLYaNjz4MTNRaU1zg.Bd-kxt.KU.F36.0.0.Bd-kx6.</code>。Facebook 現在一定知道我（Julia Evans，這個 Facebook 賬號所關聯的人）在幾分鐘之前訪問了 Old Navy 網站，並且瀏覽了“男款短絨格子花呢大衣”，因為他們可以使用這個 cookie 將數據串聯起來。</p><h3 id="這裏涉及到的是第三方-cookie" tabindex="-1">這裏涉及到的是第三方 cookie <a class="header-anchor" href="#這裏涉及到的是第三方-cookie" aria-label="Permalink to “這裏涉及到的是第三方 cookie”">​</a></h3><p>Facebook 用來追蹤我訪問了哪些網站的 cookie，屬於所謂的“第三方 cookie”，因為 Old Navy 的網站使用它為一個第三方（即 facebook.com）確認我的身份。這和用來維持登錄狀態的“第一方 cookie”有所不同。</p><p>Safari 和 Firefox 默認都會攔截許多第三方 cookie（所以需要更改 Firefox 的隱私設置，才能夠進行這個實驗），而 Chrome 目前並不進行攔截（很可能是因為 Chrome 的所有者正是一個廣告公司）。（LCTT 譯註：Chrome 可以設置阻攔）</p><h3 id="網站上的像素追蹤有很多" tabindex="-1">網站上的像素追蹤有很多 <a class="header-anchor" href="#網站上的像素追蹤有很多" aria-label="Permalink to “網站上的像素追蹤有很多”">​</a></h3><p>如我所料，網站上的像素追蹤有 <strong>很多</strong>。比如，wrangler.com 在我的瀏覽器里加載了來自不同域的 19 個不同的像素追蹤。wrangler.com 上的像素追蹤分別來自：<code>ct.pinterest.com</code>、<code>af.monetate.net</code>、<code>csm.va.us.criteo.net</code>、<code>google-analytics.com</code>、<code>dpm.demdex.net</code>、<code>google.ca</code>、<code>a.tribalfusion.com</code>、<code>data.photorank.me</code>、<code>stats.g.doubleclick.net</code>、<code>vfcorp.dl.sc.omtrdc.net</code>、<code>ib.adnxs.com</code>、<code>idsync.rlcdn.com</code>、<code>p.brsrvr.com</code>，以及 <code>adservice.google.com</code>。</p><p>Firefox 貼心地指出，如果使用 Firefox 的標準隱私設置，其中的大部分追蹤器都會被攔截：</p><p><img src="https://jvns.ca/images/firefox-helpful.png" alt=""></p><h3 id="瀏覽器的重要性" tabindex="-1">瀏覽器的重要性 <a class="header-anchor" href="#瀏覽器的重要性" aria-label="Permalink to “瀏覽器的重要性”">​</a></h3><p>瀏覽器之所以如此重要，是因為你的瀏覽器最終決定了發送你的什麼信息、發送到哪些網站。Old Navy 網站上的 Javascript 可以請求你的瀏覽器向 Facebook 發送關於你的追蹤信息，但瀏覽器可以拒絕執行。瀏覽器的決定可以是：“哈，我知道 facebook.com/tr/ 是一個像素追蹤，我不想讓我的用户被追蹤，所以我不會發送這個請求”。</p><p>瀏覽器還可以允許用户對上述行為進行配置，方法包括更改瀏覽器設置，以及安裝瀏覽器擴展（所以才會有如此多的隱私保護擴展）。</p><h3 id="摸清其中原理-實為一件趣事" tabindex="-1">摸清其中原理，實為一件趣事 <a class="header-anchor" href="#摸清其中原理-實為一件趣事" aria-label="Permalink to “摸清其中原理，實為一件趣事”">​</a></h3><p>在我看來，弄清楚 cookie/像素追蹤是怎麼用於對你進行追蹤的，實在是一件趣事（儘管有點嚇人）。我之前大概明白其中的道理，但是並沒有親自查看過像素追蹤上的 cookie，也沒有看過發送的查詢參數上究竟包含什麼樣的信息。</p><p>當然，明白了其中的原理，也就更容易降低被追蹤的概率了。</p><h3 id="可以採取的措施" tabindex="-1">可以採取的措施 <a class="header-anchor" href="#可以採取的措施" aria-label="Permalink to “可以採取的措施”">​</a></h3><p>為了儘量避免在互聯網上被追蹤，我採取了幾種簡單的措施:</p>',22)),t("ul",null,[o[12]||(o[12]=t("li",null,"安裝一個廣告攔截器（比如 ublock origin 之類）。廣告攔截器可以針對許多追蹤器的域進行攔截。",-1)),o[13]||(o[13]=t("li",null,"使用目前默認隱私保護強度更高的 Firefox/Safari，而不是 Chrome。",-1)),t("li",null,[o[10]||(o[10]=e("使用 ",-1)),i(a,{href:"https://addons.mozilla.org/en-CA/firefox/addon/facebook-container/"},{default:s(()=>[...o[9]||(o[9]=[e("Facebook Container",-1)])]),_:1}),o[11]||(o[11]=e(" 這個 Firefox 擴展。該擴展針對 Facebook 進一步採取了防止追蹤的措施。",-1))])]),o[33]||(o[33]=t("p",null,"雖然在互聯網上被追蹤的方式還有很多（尤其是在使用手機應用的時候，因為在這種情況下，你沒有和像對瀏覽器一樣的控制程度），但是能夠理解這種追蹤方法的工作原理，稍微減少一些被追蹤的可能性，也總歸是一件好事。",-1)),o[34]||(o[34]=t("hr",null,null,-1)),t("p",null,[o[15]||(o[15]=e("via: ",-1)),i(a,{href:"https://jvns.ca/blog/how-tracking-pixels-work/"},{default:s(()=>[...o[14]||(o[14]=[e("https://jvns.ca/blog/how-tracking-pixels-work/",-1)])]),_:1})]),t("p",null,[o[20]||(o[20]=e("作者：",-1)),i(a,{href:"https://jvns.ca/"},{default:s(()=>[...o[16]||(o[16]=[e("Julia Evans",-1)])]),_:1}),o[21]||(o[21]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:s(()=>[...o[17]||(o[17]=[e("lujun9972",-1)])]),_:1}),o[22]||(o[22]=e(" 譯者：",-1)),i(a,{href:"https://github.com/chen-ni"},{default:s(()=>[...o[18]||(o[18]=[e("chen-ni",-1)])]),_:1}),o[23]||(o[23]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...o[19]||(o[19]=[e("wxy",-1)])]),_:1})]),t("p",null,[o[26]||(o[26]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[24]||(o[24]=[e("LCTT",-1)])]),_:1}),o[27]||(o[27]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:s(()=>[...o[25]||(o[25]=[e("Linux中國",-1)])]),_:1}),o[28]||(o[28]=e(" 榮譽推出",-1))])])}const F=d(c,[["render",k]]);export{v as __pageData,F as default};
